solution:
counter = 0
while True:
    try:
        line = input().strip()
    except EOFError:
        break
    if line == "quit":
        break
    if line == "inc":
        counter += 1
    elif line == "dec":
        counter -= 1
    elif line == "show":
        print(counter)

